var e={"pr-1th-5-18":{e:`rv-1909`,t:[`Dad gracias en todo; porque esta es la voluntad de Dios para con vosotros en Cristo Jesús.`]},"pr-ps-100-4":{e:`rv-1909`,t:[`Entrad por sus puertas con reconocimiento, por sus atrios con alabanza: alabadle, bendecid su nombre.`]},"pr-col-3-15":{e:`rv-1909`,t:[`Y la paz de Dios gobierne en vuestros corazones, á la cual asimismo sois llamados en un cuerpo; y sed agradecidos.`]},"pr-phil-4-6":{e:`rv-1909`,t:[`Por nada estéis afanosos; sino sean notorias vuestras peticiones delante de Dios en toda oración y ruego, con hacimiento de gracias.`]},"pr-ps-107-1":{e:`rv-1909`,t:[`Alabad á Jehová, porque es bueno; porque para siempre es su misericordia.`]},"pr-jas-1-17":{e:`rv-1909`,t:[`Toda buena dádiva y todo don perfecto es de lo alto, que desciende del Padre de las luces, en el cual no hay mudanza, ni sombra de variación.`]},"pr-mic-6-8":{e:`rv-1909`,t:[`Oh hombre, él te ha declarado qué sea lo bueno, y qué pida de ti Jehová: solamente hacer juicio, y amar misericordia, y humillarte para andar con tu Dios.`]},"pr-phil-2-3":{e:`rv-1909`,t:[`Nada hagáis por contienda ó por vanagloria; antes bien en humildad, estimándoos inferiores los unos á los otros:`]},"pr-prov-11-2":{e:`rv-1909`,t:[`Cuando viene la soberbia, viene también la deshonra: mas con los humildes es la sabiduría.`]},"pr-jas-4-10":{e:`rv-1909`,t:[`Humillaos delante del Señor, y él os ensalzará.`]},"pr-eph-4-2":{e:`rv-1909`,t:[`Con toda humildad y mansedumbre, con paciencia soportando los unos á los otros en amor;`]},"pr-luke-14-11":{e:`rv-1909`,t:[`Porque cualquiera que se ensalza, será humillado; y el que se humilla, será ensalzado.`]},"pr-josh-1-9":{e:`rv-1909`,t:[`Mira que te mando que te esfuerces y seas valiente: no temas ni desmayes, porque Jehová tu Dios será contigo en donde quiera que fueres.`]},"pr-2tim-1-7":{e:`rv-1909`,t:[`Porque no nos ha dado Dios el espíritu de temor, sino el de fortaleza, y de amor, y de templanza.`]},"pr-ps-27-14":{e:`rv-1909`,t:[`Aguarda á Jehová; esfuérzate, y aliéntese tu corazón: sí, espera á Jehová.`]},"pr-isa-41-10":{e:`rv-1909`,t:[`No temas, que yo soy contigo; no desmayes, que yo soy tu Dios que te esfuerzo: siempre te ayudaré, siempre te sustentaré con la diestra de mi justicia.`]},"pr-john-16-33":{e:`rv-1909`,t:[`Estas cosas os he hablado, para que en mí tengáis paz. En el mundo tendréis aflicción: mas confiad, yo he vencido al mundo.`]},"pr-ps-112-7":{e:`rv-1909`,t:[`De mala fama no tendrá temor: su corazón está apercibido, confiado en Jehová.`]},"pr-eph-4-32":{e:`rv-1909`,t:[`Antes sed los unos con los otros benignos, misericordiosos, perdonándoos los unos á los otros, como también Dios os perdonó en Cristo.`]},"pr-col-3-13":{e:`rv-1909`,t:[`Sufriéndoos los unos á los otros, y perdonándoos los unos á los otros si alguno tuviere queja del otro: de la manera que Cristo os perdonó, así también hacedlo vosotros.`]},"pr-matt-18-21-22":{e:`rv-1909`,t:[`Entonces Pedro, llegándose á él, dijo: Señor, ¿cuántas veces perdonaré á mi hermano que pecare contra mí? ¿hasta siete?`,`Jesús le dice: No te digo hasta siete, mas aun hasta setenta veces siete.`]},"pr-prov-17-9":{e:`rv-1909`,t:[`El que cubre la prevaricación, busca amistad: mas el que reitera la palabra, aparta al amigo.`]},"pr-luke-6-37":{e:`rv-1909`,t:[`No juzguéis, y no seréis juzgados: no condenéis, y no seréis condenados: perdonad, y seréis perdonados.`]},"pr-prov-10-12":{e:`rv-1909`,t:[`El odio despierta rencillas: mas la caridad cubrirá todas las faltas.`]},"pr-jas-1-5":{e:`rv-1909`,t:[`Y si alguno de vosotros tiene falta de sabiduría, demándela á Dios, el cual da á todos abundantemente, y no zahiere; y le será dada.`]},"pr-prov-19-20":{e:`rv-1909`,t:[`Escucha el consejo, y recibe la corrección, para que seas sabio en tu vejez.`]},"pr-prov-12-15":{e:`rv-1909`,t:[`El camino del necio es derecho en su opinión: mas el que obedece al consejo es sabio.`]},"pr-ps-90-12":{e:`rv-1909`,t:[`Enséñanos de tal modo á contar nuestros días, que traigamos al corazón sabiduría.`]},"pr-jas-3-17":{e:`rv-1909`,t:[`Mas la sabiduría que es de lo alto, primeramente es pura, después pacífica, modesta, benigna, llena de misericordia y de buenos frutos, no juzgadora, no fingida.`]},"pr-prov-16-16":{e:`rv-1909`,t:[`Mejor es adquirir sabiduría que oro preciado; y adquirir inteligencia vale más que la plata.`]},"pr-acts-20-35":{e:`rv-1909`,t:[`En todo os he enseñado que, trabajando así, es necesario sobrellevar á los enfermos, y tener presente las palabras del Señor Jesús, el cual dijo: Más bienaventurada cosa es dar que recibir.`]},"pr-2cor-9-7":{e:`rv-1909`,t:[`Cada uno dé como propuso en su corazón: no con tristeza, ó por necesidad; porque Dios ama el dador alegre.`]},"pr-prov-11-25":{e:`rv-1909`,t:[`El alma liberal será engordada: y el que saciare, él también será saciado.`]},"pr-matt-6-3-4":{e:`rv-1909`,t:[`Mas cuando tú haces limosna, no sepa tu izquierda lo que hace tu derecha;`,`Para que sea tu limosna en secreto: y tu Padre que ve en secreto, él te recompensará en público.`]},"pr-1jn-3-17-18":{e:`rv-1909`,t:[`Mas el que tuviere bienes de este mundo, y viere á su hermano tener necesidad, y le cerrare sus entrañas, ¿cómo está el amor de Dios en él?`,`Hijitos míos, no amemos de palabra ni de lengua, sino de obra y en verdad.`]},"pr-prov-19-17":{e:`rv-1909`,t:[`A Jehová empresta el que da al pobre, y él le dará su paga.`]},"pr-prov-25-28":{e:`rv-1909`,t:[`Como ciudad derribada y sin muro, es el hombre cuyo espíritu no tiene rienda.`]},"pr-prov-16-32":{e:`rv-1909`,t:[`Mejor es el que tarde se aira que el fuerte; y el que se enseñorea de su espíritu, que el que toma una ciudad.`]},"pr-gal-5-22-23":{e:`rv-1909`,t:[`Mas el fruto del Espíritu es: caridad, gozo, paz, tolerancia, benignidad, bondad, fe,`,`Mansedumbre, templanza: contra tales cosas no hay ley.`]},"pr-jas-1-19":{e:`rv-1909`,t:[`Por esto, mis amados hermanos, todo hombre sea pronto para oir, tardío para hablar, tardío para airarse:`]},"pr-prov-29-11":{e:`rv-1909`,t:[`El necio da suelta á todo su espíritu; mas el sabio al fin le sosiega.`]},"pr-titus-2-12":{e:`rv-1909`,t:[`Enseñándonos que, renunciando á la impiedad y á los deseos mundanos, vivamos en este siglo templada, y justa, y píamente,`]},"pr-col-3-23":{e:`rv-1909`,t:[`Y todo lo que hagáis, hacedlo de ánimo, como al Señor, y no á los hombres;`]},"pr-gal-6-9":{e:`rv-1909`,t:[`No nos cansemos, pues, de hacer bien; que á su tiempo segaremos, si no hubiéremos desmayado.`]},"pr-prov-6-6-8":{e:`rv-1909`,t:[`Ve á la hormiga, oh perezoso, mira sus caminos, y sé sabio;`,`La cual no teniendo capitán, ni gobernador, ni señor,`,`Prepara en el verano su comida y allega en el tiempo de la siega su mantenimiento.`]},"pr-prov-21-5":{e:`rv-1909`,t:[`Los pensamientos del solícito ciertamente van á abundancia; mas todo presuroso, indefectiblemente á pobreza.`]},"pr-1cor-15-58":{e:`rv-1909`,t:[`Así que, hermanos míos amados, estad firmes y constantes, creciendo en la obra del Señor siempre, sabiendo que vuestro trabajo en el Señor no es vano.`]},"pr-prov-13-4":{e:`rv-1909`,t:[`Desea, y nada alcanza el alma del perezoso: mas el alma de los diligentes será engordada.`]},"pr-rom-12-12":{e:`rv-1909`,t:[`Gozosos en la esperanza; sufridos en la tribulación; constantes en la oración;`]},"pr-eccl-7-8":{e:`rv-1909`,t:[`Mejor es el fin del negocio que su principio: mejor es el sufrido de espíritu que el altivo de espíritu.`]},"pr-prov-14-29":{e:`rv-1909`,t:[`El que tarde se aira, es grande de entendimiento: mas el corto de espíritu engrandece el desatino.`]},"pr-1cor-13-4":{e:`rv-1909`,t:[`La caridad es sufrida, es benigna; la caridad no tiene envidia, la caridad no hace sinrazón, no se ensancha;`]},"pr-ps-37-7":{e:`rv-1909`,t:[`Calla á Jehová, y espera en él: no te alteres con motivo del que prospera en su camino, por el hombre que hace maldades.`]},"pr-prov-15-18":{e:`rv-1909`,t:[`El hombre iracundo mueve contiendas: mas el que tarde se enoja, apaciguará la rencilla.`]},"pr-john-14-27":{e:`rv-1909`,t:[`La paz os dejo, mi paz os doy: no como el mundo la da, yo os la doy. No se turbe vuestro corazón, ni tenga miedo.`]},"pr-isa-26-3":{e:`rv-1909`,t:[`Tú le guardarás en completa paz, cuyo pensamiento en ti persevera; porque en ti se ha confiado.`]},"pr-matt-5-9":{e:`rv-1909`,t:[`Bienaventurados los pacificadores: porque ellos serán llamados hijos de Dios.`]},"pr-rom-12-18":{e:`rv-1909`,t:[`Si se puede hacer, cuanto está en vosotros, tened paz con todos los hombres.`]},"pr-ps-4-8":{e:`rv-1909`,t:[`En paz me acostaré, y asimismo dormiré; porque solo tú, Jehová, me harás estar confiado.`]},"pr-ps-34-14":{e:`rv-1909`,t:[`Apártate del mal, y haz el bien; busca la paz, y síguela.`]},"pr-2cor-1-3-4":{e:`rv-1909`,t:[`Bendito sea el Dios y Padre del Señor Jesucristo, el Padre de misericordias, y el Dios de toda consolación,`,`El cual nos consuela en todas nuestras tribulaciones, para que podamos también nosotros consolar á los que están en cualquiera angustia, con la consolación con que nosotros somos consolados de Dios.`]},"pr-matt-11-28":{e:`rv-1909`,t:[`Venid á mí todos los que estáis trabajados y cargados, que yo os haré descansar.`]},"pr-matt-5-4":{e:`rv-1909`,t:[`Bienaventurados los que lloran: porque ellos recibirán consolación.`]},"pr-ps-34-18":{e:`rv-1909`,t:[`Cercano está Jehová á los quebrantados de corazón; y salvará á los contritos de espíritu.`]},"pr-ps-147-3":{e:`rv-1909`,t:[`El sana á los quebrantados de corazón, y liga sus heridas.`]},"pr-1pet-5-7":{e:`rv-1909`,t:[`Echando toda vuestra solicitud en él, porque él tiene cuidado de vosotros.`]},"pr-rom-15-13":{e:`rv-1909`,t:[`Y el Dios de esperanza os llene de todo gozo y paz creyendo, para que abundéis en esperanza por la virtud del Espíritu Santo.`]},"pr-isa-40-31":{e:`rv-1909`,t:[`Mas los que esperan á Jehová tendrán nuevas fuerzas; levantarán las alas como águilas; correrán, y no se cansarán; caminarán, y no se fatigarán.`]},"pr-rom-5-5":{e:`rv-1909`,t:[`Y la esperanza no avergüenza; porque el amor de Dios está derramado en nuestros corazones por el Espíritu Santo que nos es dado.`]},"pr-prov-23-18":{e:`rv-1909`,t:[`Porque ciertamente hay fin, y tu esperanza no será cortada.`]},"pr-heb-10-23":{e:`rv-1909`,t:[`Mantengamos firme la profesión de nuestra fe sin fluctuar; que fiel es el que prometió:`]},"pr-jer-29-11":{e:`rv-1909`,t:[`Porque yo sé los pensamientos que tengo acerca de vosotros, dice Jehová, pensamientos de paz, y no de mal, para daros el fin que esperáis.`]},"pr-ps-103-2":{e:`rv-1909`,t:[`Bendice, alma mía á Jehová, y no olvides ninguno de sus beneficios.`]},"pr-ps-118-24":{e:`rv-1909`,t:[`Este es el día que hizo Jehová: nos gozaremos y alegraremos en él.`]},"pr-ps-9-1":{e:`rv-1909`,t:[`Al Músico principal: sobre Muth-labben: Salmo de David. TE alabaré, oh Jehová, con todo mi corazón; contaré todas tus maravillas.`]},"pr-1chr-16-34":{e:`rv-1909`,t:[`Celebrad á Jehová, porque es bueno; porque su misericordia es eterna.`]},"pr-prov-27-2":{e:`rv-1909`,t:[`Alábete el extraño, y no tu boca; el ajeno, y no tus labios.`]},"pr-rom-12-16":{e:`rv-1909`,t:[`Unánimes entre vosotros: no altivos, mas acomodándoos á los humildes. No seáis sabios en vuestra opinión.`]},"pr-1pet-5-5":{e:`rv-1909`,t:[`Igualmente, mancebos, sed sujetos á los ancianos; y todos sumisos unos á otros, revestíos de humildad; porque Dios resiste á los soberbios, y da gracia á los humildes.`]},"pr-prov-22-4":{e:`rv-1909`,t:[`Riquezas, y honra, y vida, son la remuneración de la humildad y del temor de Jehová.`]},"pr-ps-56-3":{e:`rv-1909`,t:[`En el día que temo, yo en ti confío.`]},"pr-ps-31-24":{e:`rv-1909`,t:[`Esforzaos todos vosotros los que esperáis en Jehová, y tome vuestro corazón aliento.`]},"pr-heb-13-6":{e:`rv-1909`,t:[`De tal manera que digamos confiadamente: El Señor es mi ayudador; no temeré lo que me hará el hombre.`]},"pr-1chr-28-20":{e:`rv-1909`,t:[`Dijo más David á Salomón su hijo: Anímate y esfuérzate, y ponlo por obra; no temas, ni desmayes, porque el Dios Jehová, mi Dios, será contigo: él no te dejará, ni te desamparará, hasta que acabes toda la obra para el servicio de la casa de Jehová.`]},"pr-mark-11-25":{e:`rv-1909`,t:[`Y cuando estuviereis orando, perdonad, si tenéis algo contra alguno, para que vuestro Padre que está en los cielos os perdone también á vosotros vuestras ofensas.`]},"pr-prov-19-11":{e:`rv-1909`,t:[`La cordura del hombre detiene su furor; y su honra es disimular la ofensa.`]},"pr-1pet-4-8":{e:`rv-1909`,t:[`Y sobre todo, tened entre vosotros ferviente caridad; porque la caridad cubrirá multitud de pecados.`]},"pr-luke-17-4":{e:`rv-1909`,t:[`Y si siete veces al día pecare contra ti, y siete veces al día se volviere á ti, diciendo, pésame, perdónale.`]},"pr-prov-3-5-6":{e:`rv-1909`,t:[`Fíate de Jehová de todo tu corazón, y no estribes en tu prudencia.`,`Reconócelo en todos tus caminos, y él enderezará tus veredas.`]},"pr-prov-15-1":{e:`rv-1909`,t:[`La blanda respuesta quita la ira: mas la palabra áspera hace subir el furor.`]},"pr-prov-13-20":{e:`rv-1909`,t:[`El que anda con los sabios, sabio será; mas el que se allega á los necios, será quebrantado.`]},"pr-eccl-3-1":{e:`rv-1909`,t:[`Para todas las cosas hay sazón, y todo lo que se quiere debajo del cielo, tiene su tiempo:`]},"pr-heb-13-16":{e:`rv-1909`,t:[`Y de hacer bien y de la comunicación no os olvidéis: porque de tales sacrificios se agrada Dios.`]},"pr-luke-6-38":{e:`rv-1909`,t:[`Dad, y se os dará; medida buena, apretada, remecida, y rebosando darán en vuestro seno: porque con la misma medida que midiereis, os será vuelto á medir.`]},"pr-prov-3-27":{e:`rv-1909`,t:[`No detengas el bien de sus dueños, cuando tuvieres poder para hacerlo.`]},"pr-gal-6-2":{e:`rv-1909`,t:[`Sobrellevad los unos las cargas de los otros; y cumplid así la ley de Cristo.`]},"pr-prov-25-16":{e:`rv-1909`,t:[`¿Hallaste la miel? come lo que te basta; no sea que te hartes de ella, y la vomites.`]},"pr-1tim-6-6":{e:`rv-1909`,t:[`Empero grande granjería es la piedad con contentamiento.`]},"pr-heb-13-5":{e:`rv-1909`,t:[`Sean las costumbres vuestras sin avaricia; contentos de lo presente; porque él dijo: No te desampararé, ni te dejaré.`]},"pr-prov-21-23":{e:`rv-1909`,t:[`El que guarda su boca y su lengua, su alma guarda de angustias.`]},"pr-prov-10-4":{e:`rv-1909`,t:[`La mano negligente hace pobre: mas la mano de los diligentes enriquece.`]},"pr-luke-16-10":{e:`rv-1909`,t:[`El que es fiel en lo muy poco, también en lo más es fiel: y el que en lo muy poco es injusto, también en lo más es injusto.`]},"pr-prov-22-29":{e:`rv-1909`,t:[`¿Has visto hombre solícito en su obra? delante de los reyes estará; no estará delante de los de baja suerte.`]},"pr-prov-12-24":{e:`rv-1909`,t:[`La mano de los diligentes se enseñoreará: mas la negligencia será tributaria.`]},"pr-rom-5-3-4":{e:`rv-1909`,t:[`Y no sólo esto, mas aun nos gloriamos en las tribulaciones, sabiendo que la tribulación produce paciencia;`,`Y la paciencia, prueba; y la prueba, esperanza;`]},"pr-jas-1-2-3":{e:`rv-1909`,t:[`Hermanos míos, tened por sumo gozo cuando cayereis en diversas tentaciones;`,`Sabiendo que la prueba de vuestra fe obra paciencia.`]},"pr-ps-40-1":{e:`rv-1909`,t:[`Al Músico principal: Salmo de David. RESIGNADAMENTE esperé á Jehová, é inclinóse á mí, y oyó mi clamor.`]},"pr-lam-3-25-26":{e:`rv-1909`,t:[`Bueno es Jehová á los que en él esperan, al alma que le buscare.`,`Bueno es esperar callando en la salud de Jehová.`]},"pr-ps-23-1-2":{e:`rv-1909`,t:[`Salmo de David. JEHOVÁ es mi pastor; nada me faltará.`,`En lugares de delicados pastos me hará yacer: junto á aguas de reposo me pastoreará.`]},"pr-num-6-24-26":{e:`rv-1909`,t:[`Jehová te bendiga, y te guarde:`,`Haga resplandecer Jehová su rostro sobre ti, y haya de ti misericordia:`,`Jehová alce á ti su rostro, y ponga en ti paz.`]},"pr-phil-4-7":{e:`rv-1909`,t:[`Y la paz de Dios, que sobrepuja todo entendimiento, guardará vuestros corazones y vuestros entendimientos en Cristo Jesús.`]},"pr-2thess-3-16":{e:`rv-1909`,t:[`Y el mismo Señor de paz os dé siempre paz en toda manera. El Señor sea con todos vosotros.`]},"pr-ps-46-1":{e:`rv-1909`,t:[`Al Músico principal: de los hijos de Coré: Salmo sobre Alamoth. DIOS es nuestro amparo y fortaleza, nuestro pronto auxilio en las tribulaciones.`]},"pr-matt-6-34":{e:`rv-1909`,t:[`Así que, no os congojéis por el día de mañana; que el día de mañana traerá su fatiga: basta al día su afán.`]},"pr-isa-40-29":{e:`rv-1909`,t:[`El da esfuerzo al cansado, y multiplica las fuerzas al que no tiene ningunas.`]},"pr-ps-55-22":{e:`rv-1909`,t:[`Echa sobre Jehová tu carga, y él te sustentará; no dejará para siempre caído al justo.`]},"pr-rom-8-28":{e:`rv-1909`,t:[`Y sabemos que á los que á Dios aman, todas las cosas les ayudan á bien, es á saber, á los que conforme al propósito son llamados.`]},"pr-ps-42-11":{e:`rv-1909`,t:[`¿Por qué te abates, oh alma mía, y por qué te conturbas en mí? Espera á Dios; porque aun le tengo de alabar; es él salvamento delante de mí, y el Dios mío.`]},"pr-isa-43-19":{e:`rv-1909`,t:[`He aquí que yo hago cosa nueva: presto saldrá á luz: ¿no la sabréis? Otra vez pondré camino en el desierto, y ríos en la soledad.`]},"pr-heb-11-1":{e:`rv-1909`,t:[`Es pues la fe la sustancia de las cosas que se esperan, la demostración de las cosas que no se ven.`]},"pr-ps-95-2":{e:`rv-1909`,t:[`Lleguemos ante su acatamiento con alabanza; aclamémosle con cánticos.`]},"pr-ps-92-1":{e:`rv-1909`,t:[`Salmo: Canción para el día del Sábado. BUENO es alabar á Jehová, y cantar salmos á tu nombre, oh Altísimo;`]},"pr-ps-126-3":{e:`rv-1909`,t:[`Grandes cosas ha hecho Jehová con nosotros; estaremos alegres.`]},"pr-eph-5-20":{e:`rv-1909`,t:[`Dando gracias siempre de todo al Dios y Padre en el nombre de nuestro Señor Jesucristo:`]},"pr-col-3-17":{e:`rv-1909`,t:[`Y todo lo que hacéis, sea de palabra, ó de hecho, hacedlo todo en el nombre del Señor Jesús, dando gracias á Dios Padre por él.`]},"pr-1th-5-16":{e:`rv-1909`,t:[`Estad siempre gozosos.`]},"pr-ps-28-7":{e:`rv-1909`,t:[`Jehová es mi fortaleza y mi escudo: en él esperó mi corazón, y fuí ayudado; por lo que se gozó mi corazón, y con mi canción le alabaré.`]},"pr-hab-3-17-18":{e:`rv-1909`,t:[`Aunque la higuera no florecerá, ni en las vides habrá frutos; mentirá la obra de la oliva, y los labrados no darán mantenimiento, y las ovejas serán quitadas de la majada, y no habrá vacas en los corrales;`,`Con todo, yo me alegraré en Jehová, y me gozaré en el Dios de mi salud.`]},"pr-prov-16-18":{e:`rv-1909`,t:[`Antes del quebrantamiento es la soberbia; y antes de la caída la altivez de espíritu.`]},"pr-prov-15-33":{e:`rv-1909`,t:[`El temor de Jehová es enseñanza de sabiduría: y delante de la honra está la humildad.`]},"pr-jas-4-6":{e:`rv-1909`,t:[`Mas él da mayor gracia. Por esto dice: Dios resiste á los soberbios, y da gracia á los humildes.`]},"pr-phil-2-4":{e:`rv-1909`,t:[`No mirando cada uno á lo suyo propio, sino cada cual también á lo de los otros.`]},"pr-gal-6-3":{e:`rv-1909`,t:[`Porque el que estima de sí que es algo, no siendo nada, á sí mismo se engaña.`]},"pr-rom-12-3":{e:`rv-1909`,t:[`Digo pues por la gracia que me es dada, á cada cual que está entre vosotros, que no tenga más alto concepto de sí que el que debe tener, sino que piense de sí con templanza, conforme á la medida de fe que Dios repartió á cada uno.`]},"pr-prov-29-23":{e:`rv-1909`,t:[`La soberbia del hombre le abate; pero al humilde de espíritu sustenta la honra.`]},"pr-matt-5-5":{e:`rv-1909`,t:[`Bienaventurados los mansos: porque ellos recibirán la tierra por heredad.`]},"pr-ps-27-1":{e:`rv-1909`,t:[`Salmo de David. JEHOVÁ es mi luz y mi salvación: ¿de quién temeré? Jehová es la fortaleza de mi vida: ¿de quién he de atemorizarme?`]},"pr-isa-43-1":{e:`rv-1909`,t:[`Y AHORA, así dice Jehová Criador tuyo, oh Jacob, y Formador tuyo, oh Israel: No temas, porque yo te redimí; te puse nombre, mío eres tú.`]},"pr-ps-118-6":{e:`rv-1909`,t:[`Jehová está por mí: no temeré lo que me pueda hacer el hombre.`]},"pr-eph-6-10":{e:`rv-1909`,t:[`Por lo demás, hermanos míos, confortaos en el Señor, y en la potencia de su fortaleza.`]},"pr-isa-12-2":{e:`rv-1909`,t:[`He aquí Dios es salud mía; aseguraréme, y no temeré; porque mi fortaleza y mi canción es JAH Jehová, el cual ha sido salud para mí.`]},"pr-ps-121-1-2":{e:`rv-1909`,t:[`Cántico gradual. ALZARÉ mis ojos á los montes, de donde vendrá mi socorro.`,`Mi socorro viene de Jehová, que hizo los cielos y la tierra.`]},"pr-prov-28-1":{e:`rv-1909`,t:[`Huye el impío sin que nadie lo persiga: mas el justo está confiado como un leoncillo.`]},"pr-matt-14-27":{e:`rv-1909`,t:[`Mas luego Jesús les habló, diciendo: Confiad, yo soy; no tengáis miedo.`]},"pr-matt-6-14":{e:`rv-1909`,t:[`Porque si perdonareis á los hombres sus ofensas, os perdonará también á vosotros vuestro Padre celestial.`]},"pr-eph-4-26":{e:`rv-1909`,t:[`Airaos, y no pequéis; no se ponga el sol sobre vuestro enojo;`]},"pr-rom-12-17":{e:`rv-1909`,t:[`No paguéis á nadie mal por mal; procurad lo bueno delante de todos los hombres.`]},"pr-rom-12-21":{e:`rv-1909`,t:[`No seas vencido de lo malo; mas vence con el bien el mal.`]},"pr-1pet-3-9":{e:`rv-1909`,t:[`No volviendo mal por mal, ni maldición por maldición, sino antes por el contrario, bendiciendo; sabiendo que vosotros sois llamados para que poseáis bendición en herencia.`]},"pr-prov-24-29":{e:`rv-1909`,t:[`No digas: Como me hizo, así le haré; daré el pago al hombre según su obra.`]},"pr-matt-5-23-24":{e:`rv-1909`,t:[`Por tanto, si trajeres tu presente al altar, y allí te acordares de que tu hermano tiene algo contra ti,`,`Deja allí tu presente delante del altar, y vete, vuelve primero en amistad con tu hermano, y entonces ven y ofrece tu presente.`]},"pr-ps-103-12":{e:`rv-1909`,t:[`Cuanto está lejos el oriente del occidente, hizo alejar de nosotros nuestras rebeliones.`]},"pr-prov-1-5":{e:`rv-1909`,t:[`Oirá el sabio, y aumentará el saber; y el entendido adquirirá consejo;`]},"pr-prov-9-10":{e:`rv-1909`,t:[`El temor de Jehová es el principio de la sabiduría; y la ciencia de los santos es inteligencia.`]},"pr-prov-18-15":{e:`rv-1909`,t:[`El corazón del entendido adquiere sabiduría; y el oído de los sabios busca la ciencia.`]},"pr-eccl-4-9-10":{e:`rv-1909`,t:[`Mejores son dos que uno; porque tienen mejor paga de su trabajo.`,`Porque si cayeren, el uno levantará á su compañero: mas ¡ay del solo! que cuando cayere, no habrá segundo que lo levante.`]},"pr-prov-27-17":{e:`rv-1909`,t:[`Hierro con hierro se aguza; y el hombre aguza el rostro de su amigo.`]},"pr-prov-4-23":{e:`rv-1909`,t:[`Sobre toda cosa guardada guarda tu corazón; porque de él mana la vida.`]},"pr-col-4-6":{e:`rv-1909`,t:[`Sea vuestra palabra siempre con gracia, sazonada con sal; para que sepáis cómo os conviene responder á cada uno.`]},"pr-prov-12-1":{e:`rv-1909`,t:[`El que ama la corrección ama la sabiduría: mas el que aborrece la reprensión, es ignorante.`]},"pr-prov-22-9":{e:`rv-1909`,t:[`El ojo misericordioso será bendito, porque dió de su pan al indigente.`]},"pr-deut-15-11":{e:`rv-1909`,t:[`Porque no faltarán menesterosos de en medio de la tierra; por eso yo te mando, diciendo: Abrirás tu mano á tu hermano, á tu pobre, y á tu menesteroso en tu tierra.`]},"pr-isa-58-10":{e:`rv-1909`,t:[`Y si derramares tu alma al hambriento, y saciares el alma afligida, en las tinieblas nacerá tu luz, y tu oscuridad será como el medio día;`]},"pr-rom-12-13":{e:`rv-1909`,t:[`Comunicando á las necesidades de los santos; siguiendo la hospitalidad.`]},"pr-heb-13-2":{e:`rv-1909`,t:[`No olvidéis la hospitalidad, porque por ésta algunos, sin saberlo, hospedaron ángeles.`]},"pr-1pet-4-9":{e:`rv-1909`,t:[`Hospedaos los unos á los otros sin murmuraciones.`]},"pr-luke-3-11":{e:`rv-1909`,t:[`Y respondiendo, les dijo: El que tiene dos túnicas, dé al que no tiene; y el que tiene qué comer, haga lo mismo.`]},"pr-prov-11-24":{e:`rv-1909`,t:[`Hay quienes reparten, y les es añadido más: y hay quienes son escasos más de lo que es justo, mas vienen á pobreza.`]},"pr-1cor-9-25":{e:`rv-1909`,t:[`Y todo aquel que lucha, de todo se abstiene: y ellos, á la verdad, para recibir una corona corruptible; mas nosotros, incorruptible.`]},"pr-prov-14-30":{e:`rv-1909`,t:[`El corazón apacible es vida de las carnes: mas la envidia, pudrimiento de huesos.`]},"pr-prov-23-4":{e:`rv-1909`,t:[`No trabajes por ser rico; pon coto á tu prudencia.`]},"pr-eccl-5-10":{e:`rv-1909`,t:[`El que ama el dinero, no se hartará de dinero; y el que ama el mucho tener, no sacará fruto. También esto es vanidad.`]},"pr-prov-10-19":{e:`rv-1909`,t:[`En las muchas palabras no falta pecado: mas el que refrena sus labios es prudente.`]},"pr-phil-4-5":{e:`rv-1909`,t:[`Vuestra modestia sea conocida de todos los hombres. El Señor está cerca.`]},"pr-luke-12-15":{e:`rv-1909`,t:[`Y díjoles: Mirad, y guardaos de toda avaricia; porque la vida del hombre no consiste en la abundancia de los bienes que posee.`]},"pr-prov-17-27":{e:`rv-1909`,t:[`Detiene sus dichos el que tiene sabiduría: de prudente espíritu es el hombre entendido.`]},"pr-2tim-2-15":{e:`rv-1909`,t:[`Procura con diligencia presentarte á Dios aprobado, como obrero que no tiene de qué avergonzarse, que traza bien la palabra de verdad.`]},"pr-prov-14-23":{e:`rv-1909`,t:[`En toda labor hay fruto: mas la palabra de los labios solamente empobrece.`]},"pr-prov-12-11":{e:`rv-1909`,t:[`El que labra su tierra, se hartará de pan: mas el que sigue los vagabundos es falto de entendimiento.`]},"pr-eccl-11-6":{e:`rv-1909`,t:[`Por la mañana siembra tu simiente, y á la tarde no dejes reposar tu mano: porque tú no sabes cuál es lo mejor, si esto ó lo otro, ó si ambas á dos cosas son buenas.`]},"pr-rom-12-11":{e:`rv-1909`,t:[`En el cuidado no perezosos; ardientes en espíritu; sirviendo al Señor;`]},"pr-luke-19-17":{e:`rv-1909`,t:[`Y él le dice: Está bien, buen siervo; pues que en lo poco has sido fiel, tendrás potestad sobre diez ciudades.`]},"pr-prov-27-23":{e:`rv-1909`,t:[`Considera atentamente el aspecto de tus ovejas; pon tu corazón á tus rebaños:`]},"pr-1cor-10-31":{e:`rv-1909`,t:[`Si pues coméis, ó bebéis, ó hacéis otra cosa, haced lo todo á gloria de Dios.`]},"pr-heb-12-1":{e:`rv-1909`,t:[`Por tanto nosotros también, teniendo en derredor nuestro una tan grande nube de testigos, dejando todo el peso del pecado que nos rodea, corramos con paciencia la carrera que nos es propuesta,`]},"pr-isa-30-15":{e:`rv-1909`,t:[`Porque así dijo el Señor Jehová, el Santo de Israel: En descanso y en reposo seréis salvos; en quietud y en confianza será vuestra fortaleza. Y no quisisteis,`]},"pr-hab-2-3":{e:`rv-1909`,t:[`Aunque la visión tardará aún por tiempo, mas al fin hablará, y no mentirá: aunque se tardare, espéralo, que sin duda vendrá; no tardará.`]},"pr-heb-10-36":{e:`rv-1909`,t:[`Porque la paciencia os es necesaria; para que, habiendo hecho la voluntad de Dios, obtengáis la promesa.`]},"pr-col-3-12":{e:`rv-1909`,t:[`Vestíos pues, como escogidos de Dios, santos y amados, de entrañas de misericordia, de benignidad, de humildad, de mansedumbre, de tolerancia;`]},"pr-prov-25-15":{e:`rv-1909`,t:[`Con larga paciencia se aplaca el príncipe; y la lengua blanda quebranta los huesos.`]},"pr-eccl-7-9":{e:`rv-1909`,t:[`No te apresures en tu espíritu á enojarte: porque la ira en el seno de los necios reposa.`]},"pr-1th-5-14":{e:`rv-1909`,t:[`También os rogamos, hermanos, que amonestéis á los que andan desordenadamente, que consoléis á los de poco ánimo, que soportéis á los flacos, que seáis sufridos para con todos.`]},"pr-ps-29-11":{e:`rv-1909`,t:[`Jehová dará fortaleza á su pueblo: Jehová bendecirá á su pueblo en paz.`]},"pr-ps-91-1-2":{e:`rv-1909`,t:[`El que habita al abrigo del Altísimo, morará bajo la sombra del Omnipotente.`,`Diré yo á Jehová: Esperanza mía, y castillo mío; mi Dios, en él confiaré.`]},"pr-2cor-13-11":{e:`rv-1909`,t:[`Resta, hermanos, que tengáis gozo, seáis perfectos, tengáis consolación, sintáis una misma cosa, tengáis paz; y el Dios de paz y de caridad será con vosotros.`]},"pr-isa-32-17":{e:`rv-1909`,t:[`Y el efecto de la justicia será paz; y la labor de justicia, reposo y seguridad para siempre.`]},"pr-ps-46-10":{e:`rv-1909`,t:[`Estad quietos, y conoced que yo soy Dios: ensalzado he de ser entre las gentes, ensalzado seré en la tierra.`]},"pr-ps-119-165":{e:`rv-1909`,t:[`Mucha paz tienen los que aman tu ley; y no hay para ellos tropiezo.`]},"pr-matt-11-29":{e:`rv-1909`,t:[`Llevad mi yugo sobre vosotros, y aprended de mí, que soy manso y humilde de corazón; y hallaréis descanso para vuestras almas.`]},"pr-ps-16-8":{e:`rv-1909`,t:[`A Jehová he puesto siempre delante de mí: porque está á mi diestra no seré conmovido.`]},"pr-isa-41-13":{e:`rv-1909`,t:[`Porque yo Jehová soy tu Dios, que te ase de tu mano derecha, y te dice: No temas, yo te ayudé.`]},"pr-ps-30-5":{e:`rv-1909`,t:[`Porque un momento será su furor; mas en su voluntad está la vida: por la tarde durará el lloro, y á la mañana vendrá la alegría.`]},"pr-isa-66-13":{e:`rv-1909`,t:[`Como aquel á quien consuela su madre, así os consolaré yo á vosotros, y en Jerusalem tomaréis consuelo.`]},"pr-ps-73-26":{e:`rv-1909`,t:[`Mi carne y mi corazón desfallecen: mas la roca de mi corazón y mi porción es Dios para siempre.`]},"pr-john-14-1":{e:`rv-1909`,t:[`No se turbe vuestro corazón: creéis en Dios, creed también en mí.`]},"pr-2cor-4-16":{e:`rv-1909`,t:[`Por tanto, no desmayamos: antes aunque este nuestro hombre exterior se va desgastando, el interior empero se renueva de día en día.`]},"pr-ps-94-19":{e:`rv-1909`,t:[`En la multitud de mis pensamientos dentro de mí, tus consolaciones alegraban mi alma.`]},"pr-prov-17-22":{e:`rv-1909`,t:[`El corazón alegre produce buena disposición: mas el espíritu triste seca los huesos.`]},"pr-ps-62-5":{e:`rv-1909`,t:[`Alma mía, en Dios solamente reposa; porque de él es mi esperanza.`]},"pr-lam-3-22-23":{e:`rv-1909`,t:[`Es por la misericordia de Jehová que no somos consumidos, porque nunca decayeron sus misericordias.`,`Nuevas son cada mañana; grande es tu fidelidad.`]},"pr-ps-33-20":{e:`rv-1909`,t:[`Nuestra alma esperó á Jehová; nuestra ayuda y nuestro escudo es él.`]},"pr-mic-7-7":{e:`rv-1909`,t:[`Yo empero á Jehová esperaré, esperaré al Dios de mi salud: el Dios mío me oirá.`]},"pr-phil-1-6":{e:`rv-1909`,t:[`Estando confiado de esto, que el que comenzó en vosotros la buena obra, la perfeccionará hasta el día de Jesucristo;`]},"pr-prov-13-12":{e:`rv-1909`,t:[`La esperanza que se prolonga, es tormento del corazón: mas árbol de vida es el deseo cumplido.`]},"pr-1cor-13-13":{e:`rv-1909`,t:[`Y ahora permanecen la fe, la esperanza, y la caridad, estas tres: empero la mayor de ellas es la caridad.`]},"pr-ps-71-14":{e:`rv-1909`,t:[`Mas yo siempre esperaré, y añadiré sobre toda tu alabanza.`]},"pr-prov-3-3":{e:`rv-1909`,t:[`Misericordia y verdad no te desamparen; átalas á tu cuello, escríbelas en la tabla de tu corazón:`]},"pr-eph-4-29":{e:`rv-1909`,t:[`Ninguna palabra torpe salga de vuestra boca, sino la que sea buena para edificación, para que dé gracia á los oyentes.`]},"pr-prov-16-3":{e:`rv-1909`,t:[`Encomienda á Jehová tus obras, y tus pensamientos serán afirmados.`]},"pr-ps-37-5":{e:`rv-1909`,t:[`Encomienda á Jehová tu camino, y espera en él; y él hará.`]},"pr-ps-111-1":{e:`rv-1909`,t:[`Aleluya. ALABARÉ á Jehová con todo el corazón, en la compañía y congregación de los rectos.`]},"pr-ps-145-9":{e:`rv-1909`,t:[`Bueno es Jehová para con todos; y sus misericordias sobre todas sus obras.`]},"pr-ps-147-7":{e:`rv-1909`,t:[`Cantad á Jehová con alabanza, cantad con arpa á nuestro Dios.`]},"pr-ps-104-24":{e:`rv-1909`,t:[`¡Cuán muchas son tus obras, oh Jehová! Hiciste todas ellas con sabiduría: la tierra está llena de tus beneficios.`]},"pr-2cor-9-15":{e:`rv-1909`,t:[`Gracias á Dios por su don inefable.`]},"pr-1tim-4-4":{e:`rv-1909`,t:[`Porque todo lo que Dios crió es bueno, y nada hay que desechar, tomándose con hacimiento de gracias:`]},"pr-luke-17-15-16":{e:`rv-1909`,t:[`Entonces uno de ellos, como se vió que estaba limpio, volvió, glorificando á Dios á gran voz;`,`Y derribóse sobre el rostro á sus pies, dándole gracias: y éste era Samaritano.`]},"pr-col-2-7":{e:`rv-1909`,t:[`Arraigados y sobreedificados en él, y confirmados en la fe, así como habéis aprendido, creciendo en ella con hacimiento de gracias.`]},"pr-prov-18-12":{e:`rv-1909`,t:[`Antes del quebrantamiento se eleva el corazón del hombre, y antes de la honra es el abatimiento.`]},"pr-prov-16-19":{e:`rv-1909`,t:[`Mejor es humillar el espíritu con los humildes, que partir despojos con los soberbios.`]},"pr-1pet-5-6":{e:`rv-1909`,t:[`Humillaos pues bajo la poderosa mano de Dios, para que él os ensalce cuando fuere tiempo;`]},"pr-mark-9-35":{e:`rv-1909`,t:[`Entonces sentándose, llamó á los doce, y les dice: Si alguno quiere ser el primero, será el postrero de todos, y el servidor de todos.`]},"pr-john-13-14":{e:`rv-1909`,t:[`Pues si yo, el Señor y el Maestro, he lavado vuestros pies, vosotros también debéis lavar los pies los unos á los otros.`]},"pr-jas-3-13":{e:`rv-1909`,t:[`¿Quién es sabio y avisado entre vosotros? muestre por buena conversación sus obras en mansedumbre de sabiduría.`]},"pr-rom-12-10":{e:`rv-1909`,t:[`Amándoos los unos á los otros con caridad fraternal; previniéndoos con honra los unos á los otros;`]},"pr-matt-18-4":{e:`rv-1909`,t:[`Así que, cualquiera que se humillare como este niño, éste es el mayor en el reino de los cielos.`]},"pr-deut-31-8":{e:`rv-1909`,t:[`Y Jehová es el que va delante de ti; él será contigo, no te dejará, ni te desamparará; no temas, ni te intimides.`]},"pr-2chr-15-7":{e:`rv-1909`,t:[`Esforzaos empero vosotros, y no desfallezcan vuestras manos; que salario hay para vuestra obra.`]},"pr-acts-27-25":{e:`rv-1909`,t:[`Por tanto, oh varones, tened buen ánimo; porque yo confío en Dios que será así como me ha dicho;`]},"pr-josh-1-7":{e:`rv-1909`,t:[`Solamente te esfuerces, y seas muy valiente, para cuidar de hacer conforme á toda la ley que mi siervo Moisés te mandó: no te apartes de ella ni á diestra ni á siniestra, para que seas prosperado en todas las cosas que emprendieres.`]},"pr-heb-4-16":{e:`rv-1909`,t:[`Lleguémonos pues confiadamente al trono de la gracia, para alcanzar misericordia, y hallar gracia para el oportuno socorro.`]},"pr-mark-9-23":{e:`rv-1909`,t:[`Y Jesús le dijo: Si puedes creer, al que cree todo es posible.`]},"pr-2cor-12-9":{e:`rv-1909`,t:[`Y me ha dicho: Bástate mi gracia; porque mi potencia en la flaqueza se perfecciona. Por tanto, de buena gana me gloriaré más bien en mis flaquezas, porque habite en mí la potencia de Cristo.`]},"pr-phil-4-13":{e:`rv-1909`,t:[`Todo lo puedo en Cristo que me fortalece.`]},"pr-matt-5-44":{e:`rv-1909`,t:[`Mas yo os digo: Amad á vuestros enemigos, bendecid á los que os maldicen, haced bien á los que os aborrecen, y orad por los que os ultrajan y os persiguen;`]},"pr-prov-20-22":{e:`rv-1909`,t:[`No digas, yo me vengaré; espera á Jehová, y él te salvará.`]},"pr-1cor-13-5":{e:`rv-1909`,t:[`No es injuriosa, no busca lo suyo, no se irrita, no piensa el mal;`]},"pr-2cor-2-7":{e:`rv-1909`,t:[`Así que, al contrario, vosotros más bien lo perdonéis y consoléis, porque no sea el tal consumido de demasiada tristeza.`]},"pr-ps-86-5":{e:`rv-1909`,t:[`Porque tú, Señor, eres bueno y perdonador, y grande en misericordia para con todos los que te invocan.`]},"pr-eph-4-31":{e:`rv-1909`,t:[`Toda amargura, y enojo, é ira, y voces, y maledicencia sea quitada de vosotros, y toda malicia:`]},"pr-1jn-1-9":{e:`rv-1909`,t:[`Si confesamos nuestros pecados, él es fiel y justo para que nos perdone nuestros pecados, y nos limpie de toda maldad.`]},"pr-jas-5-16":{e:`rv-1909`,t:[`Confesaos vuestras faltas unos á otros, y rogad los unos por los otros, para que seáis sanos; la oración del justo, obrando eficazmente, puede mucho.`]},"pr-matt-6-12":{e:`rv-1909`,t:[`Y perdónanos nuestras deudas, como también nosotros perdonamos á nuestros deudores.`]},"pr-prov-2-6":{e:`rv-1909`,t:[`Porque Jehová da la sabiduría, y de su boca viene el conocimiento y la inteligencia.`]},"pr-prov-4-7":{e:`rv-1909`,t:[`Sabiduría ante todo: adquiere sabiduría: y ante toda tu posesión adquiere inteligencia.`]},"pr-prov-15-22":{e:`rv-1909`,t:[`Los pensamientos son frustrados donde no hay consejo; mas en la multitud de consejeros se afirman.`]},"pr-prov-20-5":{e:`rv-1909`,t:[`Como aguas profundas es el consejo en el corazón del hombre: mas el hombre entendido lo alcanzará.`]},"pr-prov-18-13":{e:`rv-1909`,t:[`El que responde palabra antes de oir, le es fatuidad y oprobio.`]},"pr-ps-119-105":{e:`rv-1909`,t:[`Nun. Lámpara es á mis pies tu palabra, y lumbrera á mi camino.`]},"pr-ps-32-8":{e:`rv-1909`,t:[`Te haré entender, y te enseñaré el camino en que debes andar: sobre ti fijaré mis ojos.`]},"pr-matt-7-24":{e:`rv-1909`,t:[`Cualquiera, pues, que me oye estas palabras, y las hace, le compararé á un hombre prudente, que edificó su casa sobre la peña;`]},"pr-prov-14-15":{e:`rv-1909`,t:[`El simple cree á toda palabra: mas el avisado entiende sus pasos.`]},"pr-2cor-9-6":{e:`rv-1909`,t:[`Esto empero digo: El que siembra escasamente, también segará escasamente; y el que siembra en bendiciones, en bendiciones también segará.`]},"pr-1tim-6-18":{e:`rv-1909`,t:[`Que hagan bien, que sean ricos en buenas obras, dadivosos, que con facilidad comuniquen;`]},"pr-isa-58-7":{e:`rv-1909`,t:[`¿No es que partas tu pan con el hambriento, y á los pobres errantes metas en casa; que cuando vieres al desnudo, lo cubras, y no te escondas de tu carne?`]},"pr-deut-15-10":{e:`rv-1909`,t:[`Sin falta le darás, y no sea tu corazón maligno cuando le dieres: que por ello te bendecirá Jehová tu Dios en todos tus hechos, y en todo lo que pusieres mano.`]},"pr-prov-14-21":{e:`rv-1909`,t:[`Peca el que menosprecia á su prójimo: mas el que tiene misericordia de los pobres, es bienaventurado.`]},"pr-1pet-4-10":{e:`rv-1909`,t:[`Cada uno según el don que ha recibido, adminístrelo á los otros, como buenos dispensadores de las diferentes gracias de Dios.`]},"pr-gal-6-10":{e:`rv-1909`,t:[`Así que, entre tanto que tenemos tiempo, hagamos bien á todos, y mayormente á los domésticos de la fe.`]},"pr-heb-6-10":{e:`rv-1909`,t:[`Porque Dios no es injusto para olvidar vuestra obra y el trabajo de amor que habéis mostrado á su nombre, habiendo asistido y asistiendo aún á los santos.`]},"pr-1tim-6-8":{e:`rv-1909`,t:[`Así que, teniendo sustento y con qué cubrirnos, seamos contentos con esto.`]},"pr-1th-4-11":{e:`rv-1909`,t:[`Y que procuréis tener quietud, y hacer vuestros negocios, y obréis de vuestras manos de la manera que os hemos mandado;`]},"pr-rom-13-13":{e:`rv-1909`,t:[`Andemos como de día, honestamente: no en glotonerías y borracheras, no en lechos y disoluciones, no en pedencias y envidia:`]},"pr-eph-5-18":{e:`rv-1909`,t:[`Y no os embriaguéis de vino, en lo cual hay disolución; mas sed llenos de Espíritu;`]},"pr-prov-17-28":{e:`rv-1909`,t:[`Aun el necio cuando calla, es contado por sabio: el que cierra sus labios es entendido.`]},"pr-jas-3-5":{e:`rv-1909`,t:[`Así también, la lengua es un miembro pequeño, y se gloría de grandes cosas. He aquí, un pequeño fuego ¡cuán grande bosque enciende!`]},"pr-1cor-6-12":{e:`rv-1909`,t:[`Todas las cosas me son lícitas, mas no todas convienen: todas las cosas me son lícitas, mas yo no me meteré debajo de potestad de nada.`]},"pr-phil-4-11-12":{e:`rv-1909`,t:[`No lo digo en razón de indigencia, pues he aprendido á contentarme con lo que tengo.`,`Sé estar humillado, y sé tener abundancia: en todo y por todo estoy enseñado, así para hartura como para hambre, así para tener abundancia como para padecer necesidad.`]},"pr-prov-10-9":{e:`rv-1909`,t:[`El que camina en integridad, anda confiado: mas el que pervierte sus caminos, será quebrantado.`]},"pr-prov-12-22":{e:`rv-1909`,t:[`Los labios mentirosos son abominación á Jehová: mas los obradores de verdad su contentamiento.`]},"pr-matt-5-37":{e:`rv-1909`,t:[`Mas sea vuestro hablar: Sí, sí; No, no; porque lo que es más de esto, de mal procede.`]},"pr-1cor-4-2":{e:`rv-1909`,t:[`Mas ahora se requiere en los dispensadores, que cada uno sea hallado fiel.`]},"pr-2cor-8-11":{e:`rv-1909`,t:[`Ahora pues, llevad también á cabo el hecho, para que como estuvisteis prontos á querer, así también lo estéis en cumplir conforme á lo que tenéis.`]},"pr-ps-15-2":{e:`rv-1909`,t:[`El que anda en integridad, y obra justicia, y habla verdad en su corazón.`]},"pr-zech-8-16":{e:`rv-1909`,t:[`Estas son las cosas que habéis de hacer: Hablad verdad cada cual con su prójimo; juzgad en vuestras puertas verdad y juicio de paz:`]},"pr-jas-1-22":{e:`rv-1909`,t:[`Mas sed hacedores de la palabra, y no tan solamente oidores, engañándoos á vosotros mismos.`]},"pr-2thess-3-13":{e:`rv-1909`,t:[`Y vosotros, hermanos, no os canséis de hacer bien.`]},"pr-1cor-13-7":{e:`rv-1909`,t:[`Todo lo sufre, todo lo cree, todo lo espera, todo lo soporta.`]},"pr-jas-5-11":{e:`rv-1909`,t:[`He aquí, tenemos por bienaventurados á los que sufren. Habéis oído la paciencia de Job, y habéis visto el fin del Señor, que el Señor es muy misericordioso y piadoso.`]},"pr-rom-8-25":{e:`rv-1909`,t:[`Empero si lo que no vemos esperamos, por paciencia esperamos.`]},"pr-heb-6-12":{e:`rv-1909`,t:[`Que no os hagáis perezosos, mas imitadores de aquellos que por la fe y la paciencia heredan las promesas.`]},"pr-2thess-3-5":{e:`rv-1909`,t:[`Y el Señor enderece vuestros corazones en el amor de Dios, y en la paciencia de Cristo.`]},"pr-luke-8-15":{e:`rv-1909`,t:[`Mas la que en buena tierra, éstos son los que con corazón bueno y recto retienen la palabra oída, y llevan fruto en paciencia.`]},"pr-col-1-11":{e:`rv-1909`,t:[`Corroborados de toda fortaleza, conforme á la potencia de su gloria, para toda tolerancia y largura de ánimo con gozo;`]},"pr-heb-6-15":{e:`rv-1909`,t:[`Y así, esperando con largura de ánimo, alcanzó la promesa.`]},"pr-rom-14-19":{e:`rv-1909`,t:[`Así que, sigamos lo que hace á la paz, y á la edificación de los unos á los otros.`]},"pr-1pet-3-11":{e:`rv-1909`,t:[`Apártase del mal, y haga bien; busque la paz, y sígala.`]},"pr-mark-9-50":{e:`rv-1909`,t:[`Buena es la sal; mas si la sal fuere desabrida, ¿con qué la adobaréis? Tened en vosotros mismos sal; y tened paz los unos con los otros.`]},"pr-prov-15-17":{e:`rv-1909`,t:[`Mejor es la comida de legumbres donde hay amor, que de buey engordado donde hay odio.`]},"pr-prov-17-1":{e:`rv-1909`,t:[`Mejor es un bocado seco, y en paz, que la casa de contienda llena de víctimas.`]},"pr-jas-3-18":{e:`rv-1909`,t:[`Y el fruto de justicia se siembra en paz para aquellos que hacen paz.`]},"pr-ps-116-7":{e:`rv-1909`,t:[`Vuelve, oh alma mía, á tu reposo; porque Jehová te ha hecho bien.`]},"pr-phil-4-9":{e:`rv-1909`,t:[`Lo que aprendisteis y recibisteis y oísteis y visteis en mí, esto haced; y el Dios de paz será con vosotros.`]},"pr-mark-4-39":{e:`rv-1909`,t:[`Y levantándose, increpó al viento, y dijo á la mar: Calla, enmudece. Y cesó el viento, y fué hecha grande bonanza.`]},"pr-rom-12-15":{e:`rv-1909`,t:[`Gozaos con los que se gozan: llorad con los que lloran.`]},"pr-ps-121-3":{e:`rv-1909`,t:[`No dará tu pie al resbaladero; ni se dormirá el que te guarda.`]},"pr-ps-121-8":{e:`rv-1909`,t:[`Jehová guardará tu salida y tu entrada, desde ahora y para siempre.`]},"pr-isa-46-4":{e:`rv-1909`,t:[`Y hasta la vejez yo mismo, y hasta las canas os soportaré yo: yo hice, yo llevaré, yo soportaré y guardaré.`]},"pr-ps-145-14":{e:`rv-1909`,t:[`Sostiene Jehová á todos los que caen, y levanta á todos los oprimidos.`]},"pr-ps-145-18":{e:`rv-1909`,t:[`Cercano está Jehová á todos los que le invocan, á todos los que le invocan de veras.`]},"pr-2cor-7-6":{e:`rv-1909`,t:[`Mas Dios, que consuela á los humildes, nos consoló con la venida de Tito:`]},"pr-isa-49-15":{e:`rv-1909`,t:[`¿Olvidaráse la mujer de lo que parió, para dejar de compadecerse del hijo de su vientre? Aunque se olviden ellas, yo no me olvidaré de ti.`]},"pr-prov-24-14":{e:`rv-1909`,t:[`Tal será el conocimiento de la sabiduría á tu alma: si la hallares tendrá recompensa, y al fin tu esperanza no será cortada.`]},"pr-ps-71-5":{e:`rv-1909`,t:[`Porque tú, oh Señor Jehová, eres mi esperanza: seguridad mía desde mi juventud.`]},"pr-ps-146-5":{e:`rv-1909`,t:[`Bienaventurado aquel en cuya ayuda es el Dios de Jacob, cuya esperanza es en Jehová su Dios:`]},"pr-ps-147-11":{e:`rv-1909`,t:[`Complácese Jehová en los que le temen, y en los que esperan en su misericordia.`]},"pr-matt-7-7":{e:`rv-1909`,t:[`Pedid, y se os dará; buscad, y hallaréis; llamad, y se os abrirá.`]},"pr-luke-1-37":{e:`rv-1909`,t:[`Porque ninguna cosa es imposible para Dios.`]},"pr-phil-3-13-14":{e:`rv-1909`,t:[`Hermanos, yo mismo no hago cuenta de haber lo ya alcanzado; pero una cosa hago: olvidando ciertamente lo que queda atrás, y extendiéndome á lo que está delante,`,`Prosigo al blanco, al premio de la soberana vocación de Dios en Cristo Jesús.`]},"pr-heb-6-19":{e:`rv-1909`,t:[`La cual tenemos como segura y firme ancla del alma, y que entra hasta dentro del velo;`]},"pr-ps-100-5":{e:`rv-1909`,t:[`Porque Jehová es bueno: para siempre es su misericordia, y su verdad por todas las generaciones.`]},"pr-1chr-16-8":{e:`rv-1909`,t:[`Confesad á Jehová, invocad su nombre, haced notorias en los pueblos sus obras.`]},"pr-ps-118-1":{e:`rv-1909`,t:[`Alabad á Jehová, porque es bueno; porque para siempre es su misericordia.`]},"pr-col-3-16":{e:`rv-1909`,t:[`La palabra de Cristo habite en vosotros en abundancia en toda sabiduría, enseñándoos y exhortándoos los unos á los otros con salmos é himnos y canciones espirituales, con gracia cantando en vuestros corazones al Señor.`]},"pr-heb-12-28":{e:`rv-1909`,t:[`Así que, tomando el reino inmóvil, retengamos la gracia por la cual sirvamos á Dios agradándole con temor y reverencia;`]},"pr-2cor-4-15":{e:`rv-1909`,t:[`Porque todas estas cosas padecemos por vosotros, para que abundando la gracia por muchos, en el hacimiento de gracias sobreabunde á gloria de Dios.`]},"pr-luke-1-46-47":{e:`rv-1909`,t:[`Entonces María dijo: engrandece mi alma al Señor;`,`Y mi espíritu se alegró en Dios mi Salvador.`]},"pr-prov-3-7":{e:`rv-1909`,t:[`No seas sabio en tu opinión: teme á Jehová, y apártate del mal;`]},"pr-matt-23-11":{e:`rv-1909`,t:[`El que es el mayor de vosotros, sea vuestro siervo.`]},"pr-1cor-4-7":{e:`rv-1909`,t:[`Porque ¿quién te distingue? ¿ó qué tienes que no hayas recibido? Y si lo recibiste, ¿de qué te glorías como si no hubieras recibido?`]},"pr-prov-25-6-7":{e:`rv-1909`,t:[`No te alabes delante del rey, ni estés en el lugar de los grandes:`,`Porque mejor es que se te diga, Sube acá, que no que seas humillado delante del príncipe que miraron tus ojos.`]},"pr-isa-66-2":{e:`rv-1909`,t:[`Mi mano hizo todas estas cosas, y así todas estas cosas fueron, dice Jehová: mas á aquél miraré que es pobre y humilde de espíritu, y que tiembla á mi palabra.`]},"pr-1pet-3-8":{e:`rv-1909`,t:[`Y finalmente, sed todos de un mismo corazón, compasivos, amándoos fraternalmente, misericordiosos, amigables;`]},"pr-prov-15-31":{e:`rv-1909`,t:[`La oreja que escucha la corrección de vida, entre los sabios morará.`]},"pr-1jn-4-18":{e:`rv-1909`,t:[`En amor no hay temor; mas el perfecto amor echa fuera el temor: porque el temor tiene pena. De donde el que teme, no está perfecto en el amor.`]},"pr-matt-10-31":{e:`rv-1909`,t:[`Así que, no temáis: más valéis vosotros que muchos pajarillos.`]},"pr-luke-12-32":{e:`rv-1909`,t:[`No temáis, manada pequeña; porque al Padre ha placido daros el reino.`]},"pr-2cor-4-8-9":{e:`rv-1909`,t:[`Estando atribulados en todo, mas no angustiados; en apuros, mas no desesperamos;`,`Perseguidos, mas no desamparados; abatidos, mas no perecemos;`]},"pr-neh-8-10":{e:`rv-1909`,t:[`Díjoles luego: Id, comed grosuras, y bebed vino dulce, y enviad porciones á los que no tienen prevenido; porque día santo es á nuestro Señor: y no os entristezcáis, porque el gozo de Jehová es vuestra fortaleza.`]},"pr-acts-23-11":{e:`rv-1909`,t:[`Y la noche siguiente, presentándosele el Señor, le dijo: Confía, Pablo; que como has testificado de mí en Jerusalem, así es menester testifiques también en Roma.`]},"pr-isa-43-5":{e:`rv-1909`,t:[`No temas, porque yo soy contigo; del oriente traeré tu generación, y del occidente te recogeré.`]},"pr-luke-15-20":{e:`rv-1909`,t:[`Y levantándose, vino á su padre. Y como aun estuviese lejos, viólo su padre, y fué movido á misericordia, y corrió, y echóse sobre su cuello, y besóle.`]},"pr-mic-7-19":{e:`rv-1909`,t:[`El tornará, él tendrá misericordia de nosotros; él sujetará nuestras iniquidades, y echará en los profundos de la mar todos nuestros pecados.`]},"pr-ps-32-5":{e:`rv-1909`,t:[`Mi pecado te declaré, y no encubrí mi iniquidad. Confesaré, dije, contra mí mis rebeliones á Jehová; y tú perdonaste la maldad de mi pecado. (Selah.)`]},"pr-ps-103-10":{e:`rv-1909`,t:[`No ha hecho con nosotros conforme á nuestras iniquidades; ni nos ha pagado conforme á nuestros pecados.`]},"pr-isa-43-25":{e:`rv-1909`,t:[`Yo, yo soy el que borro tus rebeliones por amor de mí; y no me acordaré de tus pecados.`]},"pr-gen-50-20-21":{e:`rv-1909`,t:[`Vosotros pensasteis mal sobre mí, mas Dios lo encaminó á bien, para hacer lo que vemos hoy, para mantener en vida á mucho pueblo.`,`Ahora, pues, no tengáis miedo; yo os sustentaré á vosotros y á vuestros hijos. Así los consoló, y les habló al corazón.`]},"pr-prov-1-7":{e:`rv-1909`,t:[`El principio de la sabiduría es el temor de Jehová: los insensatos desprecian la sabiduría y la enseñanza.`]},"pr-prov-3-13":{e:`rv-1909`,t:[`Bienaventurado el hombre que halla la sabiduría, y que obtiene la inteligencia:`]},"pr-prov-11-14":{e:`rv-1909`,t:[`Cuando faltaren las industrias, caerá el pueblo: mas en la multitud de consejeros hay salud.`]},"pr-prov-19-2":{e:`rv-1909`,t:[`El alma sin ciencia no es buena; y el presuroso de pies peca.`]},"pr-prov-24-5":{e:`rv-1909`,t:[`El hombre sabio es fuerte; y de pujante vigor el hombre docto.`]},"pr-matt-10-16":{e:`rv-1909`,t:[`He aquí, yo os envío como á ovejas en medio de lobos: sed pues prudentes como serpientes, y sencillos como palomas.`]},"pr-matt-5-42":{e:`rv-1909`,t:[`Al que te pidiere, dale; y al que quisiere tomar de ti prestado, no se lo rehuses.`]},"pr-rom-15-1-2":{e:`rv-1909`,t:[`Así que, los que somos más firmes debemos sobrellevar las flaquezas de los flacos, y no agradarnos á nosotros mismos.`,`Cada uno de nosotros agrade á su prójimo en bien, á edificación.`]},"pr-prov-14-31":{e:`rv-1909`,t:[`El que oprime al pobre, afrenta á su Hacedor: mas el que tiene misericordia del pobre, lo honra.`]},"pr-heb-10-24":{e:`rv-1909`,t:[`Y considerémonos los unos á los otros para provocarnos al amor y á las buenas obras;`]},"pr-1jn-4-11":{e:`rv-1909`,t:[`Amados, si Dios así nos ha amado, debemos también nosotros amarnos unos á otros.`]},"pr-jas-2-15-16":{e:`rv-1909`,t:[`Y si el hermano ó la hermana están desnudos, y tienen necesidad del mantenimiento de cada día,`,`Y alguno de vosotros les dice: Id en paz, calentaos y hartaos; pero no les diereis las cosas que son necesarias para el cuerpo: ¿qué aprovechará?`]},"pr-luke-10-36-37":{e:`rv-1909`,t:[`¿Quién, pues, de estos tres te parece que fué el prójimo de aquél que cayó en manos de los ladrones?`,`Y él dijo: El que usó con él de misericordia. Entonces Jesús le dijo: Ve, y haz tú lo mismo.`]},"pr-prov-25-27":{e:`rv-1909`,t:[`Comer mucha miel no es bueno: ni el buscar la propia gloria es gloria.`]},"pr-prov-20-1":{e:`rv-1909`,t:[`El vino es escarnecedor, la cerveza alborotadora; y cualquiera que por ello errare, no será sabio.`]},"pr-jas-1-26":{e:`rv-1909`,t:[`Si alguno piensa ser religioso entre vosotros, y no refrena su lengua, sino engañando su corazón, la religión del tal es vana.`]},"pr-prov-21-17":{e:`rv-1909`,t:[`Hombre necesitado será el que ama el deleite: y el que ama el vino y ungüentos no enriquecerá.`]},"pr-matt-6-19-20":{e:`rv-1909`,t:[`No os hagáis tesoros en la tierra, donde la polilla y el orín corrompe, y donde ladrones minan y hurtan;`,`Mas haceos tesoros en el cielo, donde ni polilla ni orín corrompe, y donde ladrones no minan ni hurtan:`]},"pr-2pet-1-5-6":{e:`rv-1909`,t:[`Vosotros también, poniendo toda diligencia por esto mismo, mostrad en vuestra fe virtud, y en la virtud ciencia;`,`Y en la ciencia templanza, y en la templanza paciencia, y en la paciencia temor de Dios;`]},"pr-prov-22-1":{e:`rv-1909`,t:[`De más estima es la buena fama que las muchas riquezas; y la buena gracia más que la plata y el oro.`]},"pr-neh-6-3":{e:`rv-1909`,t:[`Y enviéles mensajeros, diciendo: Yo hago una grande obra, y no puedo ir; porque cesaría la obra, dejándola yo para ir á vosotros.`]},"pr-prov-11-1":{e:`rv-1909`,t:[`El peso falso abominación es á Jehová: mas la pesa cabal le agrada.`]},"pr-prov-12-19":{e:`rv-1909`,t:[`El labio de verdad permanecerá para siempre: mas la lengua de mentira por un momento.`]},"pr-eph-4-25":{e:`rv-1909`,t:[`Por lo cual, dejada la mentira, hablad verdad cada uno con su prójimo; porque somos miembros los unos de los otros.`]},"pr-2tim-2-6":{e:`rv-1909`,t:[`El labrador, para recibir los frutos, es menester que trabaje primero.`]},"pr-prov-13-11":{e:`rv-1909`,t:[`Disminuiránse las riquezas de vanidad: empero multiplicará el que allega con su mano.`]},"pr-jas-1-4":{e:`rv-1909`,t:[`Mas tenga la paciencia perfecta su obra, para que seáis perfectos y cabales, sin faltar en alguna cosa.`]},"pr-isa-30-18":{e:`rv-1909`,t:[`Empero Jehová esperará para tener piedad de vosotros, y por tanto será ensalzado teniendo de vosotros misericordia: porque Jehová es Dios de juicio: bienaventurados todos los que le esperan.`]},"pr-rom-15-4":{e:`rv-1909`,t:[`Porque las cosas que antes fueron escritas, para nuestra enseñanza fueron escritas; para que por la paciencia, y por la consolación de las Escrituras, tengamos esperanza.`]},"pr-eccl-3-11":{e:`rv-1909`,t:[`Todo lo hizo hermoso en su tiempo: y aun el mundo dió en su corazón, de tal manera que no alcance el hombre la obra de Dios desde el principio hasta el cabo.`]},"pr-heb-10-35":{e:`rv-1909`,t:[`No perdáis pues vuestra confianza, que tiene grande remuneración de galardón:`]},"pr-1th-1-3":{e:`rv-1909`,t:[`Sin cesar acordándonos delante del Dios y Padre nuestro de la obra de vuestra fe, y del trabajo de amor, y de la tolerancia de la esperanza del Señor nuestro Jesucristo:`]},"pr-hos-6-3":{e:`rv-1909`,t:[`Y conoceremos, y proseguiremos en conocer á Jehová: como el alba está aparejada su salida, y vendrá á nosotros como la lluvia, como la lluvia tardía y temprana á la tierra.`]},"pr-isa-48-18":{e:`rv-1909`,t:[`¡Ojalá miraras tú á mis mandamientos! fuera entonces tu paz como un río, y tu justicia como las ondas de la mar.`]},"pr-prov-3-24":{e:`rv-1909`,t:[`Cuando te acostares, no tendrás temor; antes te acostarás, y tu sueño será suave.`]},"pr-ps-127-2":{e:`rv-1909`,t:[`Por demás os es el madrugar á levantaros, el veniros tarde á reposar, el comer pan de dolores: pues que á su amado dará Dios el sueño.`]},"pr-matt-6-26":{e:`rv-1909`,t:[`Mirad las aves del cielo, que no siembran, ni siegan, ni allegan en alfolíes; y vuestro Padre celestial las alimenta. ¿No sois vosotros mucho mejores que ellas?`]},"pr-prov-16-7":{e:`rv-1909`,t:[`Cuando los caminos del hombre son agradables á Jehová, aun á sus enemigos pacificará con él.`]},"pr-ps-23-3":{e:`rv-1909`,t:[`Confortará mi alma; guiaráme por sendas de justicia por amor de su nombre.`]},"pr-matt-6-28-29":{e:`rv-1909`,t:[`Y por el vestido ¿por qué os congojáis? Reparad los lirios del campo, cómo crecen; no trabajan ni hilan;`,`Mas os digo, que ni aun Salomón con toda su gloria fué vestido así como uno de ellos.`]},"pr-john-14-18":{e:`rv-1909`,t:[`No os dejaré huérfanos: vendré á vosotros.`]},"pr-1cor-10-13":{e:`rv-1909`,t:[`No os ha tomado tentación, sino humana: mas fiel es Dios, que no os dejará ser tentados más de lo que podéis llevar; antes dará también juntamente con la tentación la salida, para que podáis aguantar.`]},"pr-zeph-3-17":{e:`rv-1909`,t:[`Jehová en medio de ti, poderoso, él salvará; gozaráse sobre ti con alegría, callará de amor, se regocijará sobre ti con cantar.`]},"pr-jer-31-13":{e:`rv-1909`,t:[`Entonces la virgen se holgará en la danza, los mozos y los viejos juntamente; y su lloro tornaré en gozo, y los consolaré, y los alegraré de su dolor.`]},"pr-john-16-22":{e:`rv-1909`,t:[`También, pues, vosotros ahora ciertamente tenéis tristeza; mas otra vez os veré, y se gozará vuestro corazón, y nadie quitará de vosotros vuestro gozo.`]},"pr-isa-57-15":{e:`rv-1909`,t:[`Porque así dijo el Alto y Sublime, el que habita la eternidad, y cuyo nombre es el Santo: Yo habito en la altura y la santidad, y con el quebrantado y humilde de espíritu, para hacer vivir el espíritu de los humildes, y para vivificar el corazón de los quebrantados.`]},"pr-lam-3-31-32":{e:`rv-1909`,t:[`Porque el Señor no desechará para siempre:`,`Antes si afligiere, también se compadecerá según la multitud de sus misericordias.`]},"pr-rom-4-18":{e:`rv-1909`,t:[`El creyó en esperanza contra esperanza, para venir á ser padre de muchas gentes, conforme á lo que le había sido dicho: Así será tu simiente.`]},"pr-ps-37-4":{e:`rv-1909`,t:[`Pon asimismo tu delicia en Jehová, y él te dará las peticiones de tu corazón.`]},"pr-jer-17-7":{e:`rv-1909`,t:[`Bendito el varón que se fía en Jehová, y cuya confianza es Jehová.`]},"pr-mark-11-24":{e:`rv-1909`,t:[`Por tanto, os digo que todo lo que orando pidiereis, creed que lo recibiréis, y os vendrá.`]},"pr-isa-60-1":{e:`rv-1909`,t:[`Levántate, resplandece; que ha venido tu lumbre, y la gloria de Jehová ha nacido sobre ti.`]},"pr-ps-16-11":{e:`rv-1909`,t:[`Me mostrarás la senda de la vida: hartura de alegrías hay con tu rostro; deleites en tu diestra para siempre.`]}};export{e as default};